    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '1: What is the primary causative agent associated with > 99% of Cervical Cancers?', '["Herpes Simplex Virus", "Human Papillomavirus (HPV)", "Chlamydia trachomatis", "HIV"]', 1, 'HPV 16 and 18 are the most common high-risk genotypes. (ACOG)'),
    (v_topic_id, '2: Which "High-Risk" HPV genotypes are responsible for approximately 70% of cervical cancers?', '["6 and 11", "16 and 18", "31 and 33", "45 and 52"]', 1, '16 and 18 are the major oncogenic types. (Williams Obstetrics)'),
    (v_topic_id, '3: HPV genotypes 6 and 11 are primarily associated with:', '["Cervical cancer", "Condyloma acuminata (Genital warts)", "Ovarian cancer", "Endometrial hyperplasia"]', 1, 'Low-risk HPV types. (Beckmann)'),
    (v_topic_id, '4: At what age should cervical cancer screening (Pap test) typically BEGIN for an average-risk woman?', '["At the start of sexual activity", "Age 18", "Age 21", "Age 25"]', 2, 'Current ACOG guidelines recommend starting at 21, regardless of sexual history. (ACOG)'),
    (v_topic_id, '5: What is the recommended screening interval for women aged 21-29?', '["Annually", "Every 2 years", "Every 3 years (Cytology alone)", "Every 5 years"]', 2, 'Cytology alone every 3 years. HPV testing is not recommended for routine screening < 30. (ACOG)'),
    (v_topic_id, '6: For women aged 30-65, what is the preferred "Co-testing" interval?', '["Every 3 years", "Every 5 years (Cytology + HPV testing)", "Every year", "Every 10 years"]', 1, 'Co-testing every 5 years is the preferred strategy. (ACOG)'),
    (v_topic_id, '7: When can cervical cancer screening be DISCONTINUED in an average-risk woman?', '["Age 50", "Age 65 (if they have had adequate negative prior screening)", "Age 75", "Never"]', 1, 'Adequate screening = 3 consecutive negative paps or 2 negative co-tests in last 10 years. (ACOG)'),
    (v_topic_id, '8: A woman who has had a "Total Hysterectomy" (cervix removed) for BENIGN reasons and has NO history of high-grade dysplasia requires:', '["Continued screening every 3 years", "No further screening", "Screening every 5 years", "Annual exams"]', 1, 'If the cervix was removed for benign reasons and no high-grade CIN history exists, screening stops. (Beckmann)'),
    (v_topic_id, '9: "Transformation Zone" of the cervix is the area where:', '["Squamous epithelium meets columnar epithelium", "The vagina meets the vulva", "The uterus meets the tubes", "None"]', 0, 'Most cervical cancers and precursors arise here. (Williams)'),
    (v_topic_id, '10: A Pap smear result of "ASC-US" (Atypical Squamous Cells of Undetermined Significance) in a 25-year-old. Best next step?', '["Colposcopy", "Reflex HPV testing or repeat pap in 1 year", "Immediate LEEP", "C-section"]', 1, 'Reflex HPV is the preferred management for ASC-US. (ACOG)'),
    (v_topic_id, '11: If a woman > 25 has ASC-US and the "Reflex HPV" is POSITIVE, what is the next step?', '["Repeat pap in 1 year", "Colposcopy", "LEEP", "Hysterectomy"]', 1, 'Positive high-risk HPV with ASC-US warrants colposcopy. (ACOG)'),
    (v_topic_id, '12: A Pap smear result of "LSIL" (Low-grade Squamous Intraepithelial Lesion) in a 22-year-old. Best management?', '["Colposcopy", "Repeat pap in 1 year", "Immediate LEEP", "Cryotherapy"]', 1, 'In women < 25, LSIL is managed conservatively due to high regression rates. (ACOG)'),
    (v_topic_id, '13: A Pap smear result of "HSIL" (High-grade Squamous Intraepithelial Lesion) in a 30-year-old. Best next step?', '["Repeat pap in 1 year", "Colposcopy (or immediate LEEP in some cases)", "Antibiotics", "Wait"]', 1, 'HSIL is a high-grade precursor requiring evaluation. (ACOG)'),
    (v_topic_id, '14: During "Colposcopy," what agent is applied to the cervix to highlight abnormal areas?', '["Iodine only", "3-5% Acetic Acid (Vinegar)", "Saline", "Alcohol"]', 1, 'Causes "acetowhite" changes in areas with high nuclear density. (Beckmann)'),
    (v_topic_id, '15: "Schiller Test" uses which agent to identify abnormal (non-glycogenated) cervical tissue?', '["Acetic acid", "Lugol''s Iodine", "Water", "Formalin"]', 1, 'Abnormal tissue fails to take up the dark brown iodine stain. (Williams)'),
    (v_topic_id, '16: A "CIN 1" biopsy result indicates:', '["Invasive cancer", "Low-grade dysplasia involving the lower 1/3 of the epithelium", "High-grade dysplasia", "Normal tissue"]', 1, 'Most CIN 1 lesions regress spontaneously. (ACOG)'),
    (v_topic_id, '17: Management of a persistent "CIN 2/3" lesion?', '["Observation", "Excisional procedure (LEEP or Cold Knife Cone) or Ablative (Cryo/Laser)", "Wait until pregnancy", "Antibiotics"]', 1, 'High-grade lesions have significant malignant potential. (ACOG)'),
    (v_topic_id, '18: "LEEP" stands for:', '["Large Endometrial Excision Procedure", "Loop Electrosurgical Excision Procedure", "Light Energy Estrogen Process", "None"]', 1, 'Uses a wire loop to remove the transformation zone. (Beckmann)'),
    (v_topic_id, '19: "Cold Knife Cone" (CKC) biopsy is preferred over LEEP when:', '["The patient is young", "Microinvasion is suspected or the lesion extends deep into the endocervical canal", "Cost is an issue", "None"]', 1, 'Provides a better specimen for margin assessment and depth. (Williams)'),
    (v_topic_id, '20: What is a major obstetrical risk of excisional cervical procedures like CKC or LEEP?', '["Infertility", "Cervical Insufficiency and Preterm Birth", "Macrosomia", "Placenta Previa"]', 1, 'Shortening or scarring the cervix increases PTB risk. (ACOG)'),
    (v_topic_id, '21: "Cervical Cancer" most commonly presents with which symptom?', '["Abdominal pain", "Post-coital bleeding", "Weight gain", "Fever"]', 1, 'Bleeding after intercourse is a classic red flag. (Beckmann)'),
    (v_topic_id, '22: The most common histological type of cervical cancer is:', '["Adenocarcinoma", "Squamous Cell Carcinoma", "Clear cell", "Sarcoma"]', 1, 'Accounts for ~80% of cases. (Williams)'),
    (v_topic_id, '23: "Adenocarcinoma" of the cervix arises from which cells?', '["Squamous cells", "Columnar glandular cells", "Basal cells", "Muscle cells"]', 1, 'Often harder to detect on Pap as it starts in the endocervical canal. (Beckmann)'),
    (v_topic_id, '24: "Cervical Cancer" is staged using which system?', '["TNM", "FIGO Clinical Staging (Stage I-IV)", "Gleason", "Bishop"]', 1, 'Staging is primarily clinical (exam, imaging) rather than purely surgical. (Williams)'),
    (v_topic_id, '25: "Stage I" Cervical Cancer is:', '["Confined to the cervix", "Invaded the bladder", "Spread to lungs", "Invaded the vagina"]', 0, 'Standard FIGO staging. (Williams)'),
    (v_topic_id, '26: "Stage II" Cervical Cancer:', '["Confined to cervix", "Extends beyond the uterus but NOT to the pelvic wall or lower 1/3 of vagina", "Involves bladder", "Bone mets"]', 1, 'May involve the parametria (IIB). (Beckmann)'),
    (v_topic_id, '27: "Stage III" Cervical Cancer:', '["Mets to liver", "Extends to the pelvic wall or lower 1/3 of the vagina, or causes hydronephrosis", "Confined to cervix", "None"]', 1, 'Indicates more advanced local spread. (Williams)'),
    (v_topic_id, '28: "Stage IV" Cervical Cancer involves:', '["The cervix only", "Invasion of the bladder/rectum mucosa or distant metastasis", "The upper vagina", "The uterus"]', 1, 'Advanced disease. (Beckmann)'),
    (v_topic_id, '29: The most common cause of death in advanced cervical cancer is:', '["Liver failure", "Uremia (Renal failure from ureteral obstruction)", "Lung hemorrhage", "Stroke"]', 1, 'Local tumor growth obstructs the ureters. (Williams)'),
    (v_topic_id, '30: Primary treatment for Stage IA1 cervical cancer?', '["Radiation only", "Simple Hysterectomy or Cone biopsy (if fertility is desired)", "Pelvic exenteration", "Chemotherapy"]', 1, 'Conservative management for very early stage. (ACOG)'),
    (v_topic_id, '31: Primary treatment for Stage IB1 (visible lesion < 4cm)?', '["Chemotherapy only", "Radical Hysterectomy and pelvic lymphadenectomy (or radiation)", "Wait and see", "Aspirin"]', 1, 'Radical surgery is curative in early stages. (Beckmann)'),
    (v_topic_id, '32: Primary treatment for "locally advanced" disease (Stage IIB, III, IV)?', '["Surgery only", "Concurrent Chemoradiation (Cisplatin + Radiation)", "Antibiotics", "Home rest"]', 1, 'Surgery is not effective once the parametria are involved to the side wall. (Williams)'),
    (v_topic_id, '33: "Radical Hysterectomy" differs from simple hysterectomy by removing:', '["Only the fundus", "The cervix, parametria, and the upper 1-2 cm of the vagina", "The ovaries only", "The bladder"]', 1, 'Standard "Wertheim" procedure. (Beckmann)'),
    (v_topic_id, '34: "HPV Vaccine" (Gardasil 9) protects against which genotypes?', '["6, 11, 16, 18, 31, 33, 45, 52, 58", "16 and 18 only", "6 and 11 only", "All HPV types"]', 0, 'Highly effective primary prevention. (CDC/ACOG)'),
    (v_topic_id, '35: At what age is the HPV vaccine ROUTINELY recommended for boys and girls?', '["Age 9", "Age 11 or 12", "Age 18", "Age 21"]', 1, 'Can be started as early as age 9. (CDC)'),
    (v_topic_id, '36: For children starting the HPV vaccine series BEFORE age 15, how many doses are required?', '["One", "Two (at 0 and 6-12 months)", "Three", "Annual"]', 1, 'The two-dose schedule is effective in younger patients. (CDC)'),
    (v_topic_id, '37: For individuals starting the HPV vaccine series AFTER age 15, how many doses are required?', '["One", "Two", "Three (at 0, 1-2, and 6 months)", "None"]', 2, 'Older patients require three doses for full immunity. (CDC)'),
    (v_topic_id, '38: HPV vaccine is approved and recommended for individuals up to age:', '["21", "26 (catch-up); can be discussed up to 45", "50", "No limit"]', 1, 'Standard catch-up is to age 26. (ACOG)'),
    (v_topic_id, '39: "Clear Cell Adenocarcinoma" of the vagina/cervix is associated with in-utero exposure to:', '["Thalidomide", "Diethylstilbestrol (DES)", "Alcohol", "Warfarin"]', 1, 'Classic association for "DES daughters." (Williams)'),
    (v_topic_id, '40: "Endometrial Cancer" is the most common gynecological malignancy in which type of country?', '["Developing countries", "Developed countries (e.g., USA)", "Tropical countries", "None"]', 1, 'Cervical cancer is more common globally, but Endometrial is top in the US. (Beckmann)'),
    (v_topic_id, '41: What is the most significant RISK FACTOR for Endometrial Cancer?', '["Smoking", "Unopposed Estrogen (Obesity, PCOS, late menopause, nulliparity)", "Multiple partners", "OCP use"]', 1, 'Estrogen stimulates the endometrium without progesterone to stabilize it. (ACOG)'),
    (v_topic_id, '42: "Obesity" increases endometrial cancer risk because adipose tissue:', '["Produces progesterone", "Converts androstenedione to estrone (estrogen) via aromatase", "Destroys the uterus", "None"]', 1, 'Peripheral conversion leads to chronically high estrogen levels. (Williams)'),
    (v_topic_id, '43: "Lynch Syndrome" (HNPCC) increases the risk of which gynecological cancer (besides Colon)?', '["Cervical", "Endometrial (up to 40-60% lifetime risk)", "Vulvar", "Breast"]', 1, 'Requires screening and often prophylactic surgery. (Beckmann)'),
    (v_topic_id, '44: "Postmenopausal Bleeding" (PMB) should be considered _____ until proven otherwise.', '["Normal", "Cancer (Endometrial)", "A sign of youth", "Infection"]', 1, 'Requires immediate evaluation with TVUS or biopsy. (ACOG)'),
    (v_topic_id, '45: What is the first-line evaluation for a woman with Postmenopausal Bleeding?', '["Pelvic exam only", "Transvaginal Ultrasound (TVUS) to check endometrial thickness", "Immediate hysterectomy", "Pap smear"]', 1, 'Endometrial thickness < 4mm has a very high negative predictive value. (ACOG)'),
    (v_topic_id, '46: If Endometrial Thickness is > _____ mm in a postmenopausal woman with bleeding, an Endometrial Biopsy (EMB) is required.', '["2", "4", "8", "10"]', 1, 'Standard threshold for biopsy. (Beckmann)'),
    (v_topic_id, '47: What is the "Gold Standard" for diagnosing endometrial cancer?', '["Ultrasound", "Endometrial Biopsy (EMB) or D&C", "MRI", "Blood test"]', 1, 'Tissue diagnosis is mandatory. (Williams)'),
    (v_topic_id, '48: "Endometrial Hyperplasia with ATYPIA" is considered:', '["Benign", "A premalignant condition with ~30% risk of progression to cancer", "Infectious", "None"]', 1, 'Warrants hysterectomy in postmenopausal women. (ACOG)'),
    (v_topic_id, '49: "Type I" Endometrial Cancer (Endometroid) is characterized by:', '["Estrogen dependence, low grade, and good prognosis", "Estrogen independence and high grade", "Young age", "None"]', 0, 'Most common type, associated with obesity. (Williams)'),
    (v_topic_id, '50: "Type II" Endometrial Cancer (Serous, Clear Cell) is characterized by:', '["Estrogen dependence", "Estrogen independence, high grade, and poor prognosis", "Obesity", "None"]', 1, 'More aggressive and common in older, thin women. (Beckmann)'),
    (v_topic_id, '51: Treatment for "Endometrial Hyperplasia WITHOUT atypia" in a woman desiring fertility?', '["Hysterectomy", "Progestin therapy (e.g., Megace or IUD) and repeat biopsy", "Radiation", "Weight gain"]', 1, 'Progestins thin the lining and reverse hyperplasia. (ACOG)'),
    (v_topic_id, '52: Standard treatment for Endometrial Cancer?', '["Radiation only", "Total Hysterectomy and Bilateral Salpingo-Oophorectomy (TH/BSO) with staging", "Chemotherapy only", "Wait"]', 1, 'Surgical staging is the primary management. (Williams)'),
    (v_topic_id, '53: Staging for Endometrial Cancer is:', '["Clinical (like Cervix)", "Surgical (based on pathology from hysterectomy)", "Radiological", "None"]', 1, 'Includes assessment of depth of myometrial invasion. (FIGO)'),
    (v_topic_id, '54: "Stage I" Endometrial Cancer is:', '["Confined to the uterine body", "Invaded the cervix", "Invaded the bladder", "Mets to lungs"]', 0, 'Majority of cases are caught at this stage due to early bleeding. (Beckmann)'),
    (v_topic_id, '55: "Stage II" Endometrial Cancer:', '["Confined to uterus", "Invaded cervical stroma but not beyond the uterus", "Invaded vagina", "None"]', 1, 'Standard FIGO staging. (Williams)'),
    (v_topic_id, '56: Which medication used for Breast Cancer increases the risk of Endometrial Cancer?', '["Trastuzumab", "Tamoxifen (due to its estrogenic effect on the uterus)", "Anastrozole", "Letrozole"]', 1, 'Requires annual pelvic exams but not routine biopsy unless bleeding occurs. (ACOG)'),
    (v_topic_id, '57: "Oral Contraceptive Pills" (OCPs) _____ the risk of Endometrial Cancer.', '["Increase", "Decrease (by ~50%)", "Do not affect", "None"]', 1, 'Progestin component stabilizes the lining. (Williams)'),
    (v_topic_id, '58: Endometrial cancer spreads primarily via which route?', '["Hematogenous", "Direct extension and Lymphatic spread", "Only in the blood", "None"]', 1, 'Pelvic and para-aortic lymph nodes are common sites of spread. (Beckmann)'),
    (v_topic_id, '59: "Stage III" Endometrial Cancer involves:', '["Distant mets", "Local/regional spread (vagina, adnexa, or lymph nodes)", "Bladder", "None"]', 1, 'Increased risk of recurrence. (Williams)'),
    (v_topic_id, '60: "Stage IV" Endometrial Cancer involves:', '["Uterus only", "Invasion of bladder/rectum or distant metastasis (e.g., lungs)", "Cervix", "None"]', 1, 'Advanced disease. (Beckmann)');
